class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_mib = monthly_limit_mib
        self.monthly_files = {}  # Maps month -> set of file names uploaded that month
        self.file_sizes = {}     # Maps (month, name) -> size_bytes

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("File size cannot be 0")

        # Check if file already exists for this month
        if month in self.monthly_files and name in self.monthly_files[month]:
            # File already uploaded this month, no change to quota
            return

        # Calculate current usage for this month
        current_usage = self.used_bytes(month)

        # Check if adding this file would exceed the limit
        new_usage = current_usage + size_bytes
        limit_bytes = self.monthly_limit_mib * 1024 * 1024

        if new_usage > limit_bytes:
            raise ValueError("Upload would exceed monthly quota")

        # Add the file to tracking
        if month not in self.monthly_files:
            self.monthly_files[month] = set()
        self.monthly_files[month].add(name)
        self.file_sizes[(month, name)] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Deleting a file does not give back quota in the current month
        # So we just remove it from our tracking
        if month in self.monthly_files and name in self.monthly_files[month]:
            self.monthly_files[month].remove(name)
            # Remove from file_sizes as well
            if (month, name) in self.file_sizes:
                del self.file_sizes[(month, name)]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        if month not in self.monthly_files:
            return 0

        total = 0
        for name in self.monthly_files[month]:
            if (month, name) in self.file_sizes:
                total += self.file_sizes[(month, name)]
        return total
